import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import path from'node:path';const dir='database/migrations';const sql=fs.readdirSync(dir).sort().map((f:any)=>fs.readFileSync(path.join(dir,f),'utf8')).join('\n');for(const [n,re] of Object.entries({uniqueIndex:/CREATE UNIQUE INDEX IF NOT EXISTS uq_zsl3_source_fact_identity/,authorityPointer:/zsl3_authority_state/,upstreamRevocation:/zsl3_bindings_still_valid/,certGuard:/zsl3_certification_guard/,rbac:/CREATE ROLE zsl3_reader/,immutable:/zsl3_prevent_mutation/,zipZcta:/POSTAL_CODE/,economicPressure:/economic_pressure_index|feature_definition_coverage/}))test(n,()=>assert.match(sql,re as RegExp));test('no invalid unique coalesce constraint',()=>assert.doesNotMatch(sql,/UNIQUE\([^;]*COALESCE\(/s));
